<div class="ux-summary-strip"><div><strong><?= e($employee['full_name']) ?></strong><?php if(($employee['status']??'')!=='active'): ?> · аккаунт неактивен<?php endif; ?></div><div><?= count($ledger) ?> операций</div></div>
