<?php else: ?><div class="table-scroll"><table class="table"><thead><tr><th>Дата</th><th>Операция</th><th>Источник</th><th>Сумма</th><th>Основание</th><th>Сальдо</th></tr></thead><tbody><?php foreach($ledger as $row): $cancelled=($row['status']??'')==='CANCELLED'; ?><tr class="<?= $cancelled?'is-muted':'' ?>"><td><?= e(date('d.m.Y',strtotime($row['operation_date']))) ?></td><td><span class="<?= $row['movement_type']==='PAYMENT'?'badge badge-neutral':'badge badge-ok' ?>"><?= $row['movement_type']==='PAYMENT'?'Выплата':'Возврат' ?></span><?php if($cancelled): ?> <span class="badge badge-danger">Отменено</span><?php endif; ?></td><td><?= $row['source_type']==='BANK'?'Расчётный счёт':'Касса' ?><div class="field-note"><?= e($row['money_account_name']??'') ?></div></td><td class="col-mono"><?= $fmt($row['amount']) ?> ₽</td><td><?= e($row['purpose']?:($row['note']?:'—')) ?></td><td class="col-mono"><strong><?= $fmt($row['running_balance']) ?> ₽</strong></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
